WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM payments), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN amount >= 1400 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS new_group_flag_tier, COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_rows, APPROX_PERCENTILE(new_group_flag, ARRAY(0.25, 0.5, 0.75)) AS new_group_flag_quartiles, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM islands GROUP BY amount_tier, quarter_start, new_group_flag_tier;
